<script lang="ts">import {putSpace} from '$lib/files/store';import {slugify} from '$lib/model';import type {Space} from '$lib/files/model.js';export let space:Space|undefined=undefined;export let onSaved:(id:string)=>void=()=>{};export let onCancel:()=>void=()=>{};let name=space?.name||'',quota=space?.quota||1024,access:Space['access']=space?.access||'Private',error='';function submit(){try{if(access==='Public read'&&space?.access!=='Public read'&&!window.confirm('Public read is a sample setting. In production anyone with an object URL could read it. Continue?'))return;const id=space?.id||slugify(name);putSpace({id,name,quota,access},!!space);error='';onSaved(id);}catch(e){error=e instanceof Error?e.message:'Storage settings could not be saved.';}}</script>
<form class="card stack" on:submit|preventDefault={submit}><div><h3>{space?'Storage settings':'Create storage space'}</h3><p class="subtitle">Independent storage · this server</p></div><label class="field">Storage name<input required maxlength="80" bind:value={name} placeholder="e.g. Dev_2026"/></label><div class="grid2"><label class="field">Maximum capacity (MB)<input type="number" min="1" max="1048576" step="1" required bind:value={quota}/><small>Maximum capacity; does not reserve server disk space.</small></label><label class="field">Access<select bind:value={access}><option>Private</option><option>Public read</option></select><small>Private is recommended. Public read never allows anonymous writes.</small></label></div><div class="callout">No project, framework or domain required. Use sample files only.</div>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="native-actions"><button class="btn secondary" type="button" on:click={onCancel}>Cancel</button><button class="btn primary" type="submit">{space?'Save changes':'Create storage'}</button></div></form>
